mapper.select:
SELECT
	email
	, user_type
from user u 
left outer join user_person p on u.user_id = p.user_id 
left outer join user_company c on u.user_id = c.user_id
where u.user_type = #{userType}

	and u.user_name = #{userName}
	and u.phone = #{phone}


	and c.ceo_name = #{ceoName}
	and c.biz_reg_no = #{bizRegNo}

